{
  "anyOf": [
    {
      "description": "**DEPRECATED AT v2.1**\nA reason or reference in relation to a payment, set to facilitate a structured Debtor reference consisting of:\n\n* For payments to Merchants: TPP ID, Merchant ID, BIC for the Creditor Account, followed by freeform text to a maximum of 120 characters.\n\n* For other payments: TPP ID and BIC for the Creditor Account, followed by freeform text to a maximum of 120 characters.\n\nThe TPP ID value will match the organization ID value from the Trust Framework, and therefore will be a v4 UUID.\n\nThe Merchant ID wil be as per the existing Aani Core rules for the Merchant identification, and will incorporate the Trade License number for the Merchant.\n\nA BIC is specific according to the standard format for ISO 20022, and can therefore be either 8 or 11 characters in length.\n\nIf the value of the concatenated string exceeds 120 characters, the TPP must omit or truncate the freeform element of the reference.\n",
      "type": "string",
      "minLength": 1,
      "maxLength": 120,
      "pattern": "^TPP=[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12},(Merchant=[A-Z0-9]{3}-[A-Z]{4}-TL.+-[0-9]{4}|),BIC=[A-Z0-9]{4}[A-Z0-9]{2}[A-Z0-9]{2}([A-Z0-9]{3}){0,1}($|,.+$)",
      "deprecated": true
    },
    {
      "description": "A Debtor Reference is a note is for the reference of a given User that may be available as\nadditional information in relation to a given payment instruction.",
      "type": "string",
      "minLength": 1,
      "maxLength": 35,
      "pattern": "^[A-Za-z0-9 \\/?:().,'+-]+$"
    }
  ]
}

{
  "anyOf": [
    {
      "description": "**DEPRECATED AT v2.1**\nA reason or reference in relation to a payment, set to facilitate a structured Creditor reference consisting of:\n\n* TPP ID and BIC for the Debtor Account, followed by freeform text to a maximum of 120 characters.\n\nThe TPP ID value will match the organization ID value from the Trust Framework, and therefore will be a v4 UUID.\n\nA BIC is specific according to the standard format for ISO 20022, and can therefore be either 8 or 11 characters in length.\n\nIf the value of the concatenated string exceeds 120 characters, the TPP must first omit or truncate the freeform element of the reference.\n",
      "type": "string",
      "minLength": 1,
      "maxLength": 120,
      "pattern": "^TPP=[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12},BIC=[A-Z0-9]{4}[A-Z0-9]{2}[A-Z0-9]{2}([A-Z0-9]{3}){0,1}($|,.+$)",
